/// <summary>
/// MPJ_2864_CreditLimitBalance 03/11/2021
/// Standard find and exist method where added to the new table
/// </summary>
public class METCustTable extends common
{
}

Method.Source:
    /// <summary>
    /// MPJ_2864_CreditLimitBalance 03/11/2021
    /// find method finds record in METCustTable
    /// </summary>
    /// <param name = "_custAccount">CustomerAccount</param>
    /// <param name = "_forUpdate">true/false</param>
    /// <returns>Returns METCustTable</returns>
    static METCustTable find(CustAccount _custAccount, boolean _forUpdate = false)
    {
        METCustTable metCustTable;

        if (_custAccount)
        {
            metCustTable.selectForUpdate(_forUpdate);
          
            select firstonly metCustTable
              where metCustTable.AccountNum == _custAccount;
        }

        return metCustTable;
    }

/// <summary>
/// MPJ_2864_CreditLimitBalance 03/11/2021
/// This method is used to check if a record that fulfils the specified key actually exists.
/// exist method
/// </summary>
/// <param name = "_custAccount">CustomerAccount</param>
/// <returns>returns true or false depedning if records exists</returns>
static boolean exist(CustAccount _custAccount)
{
    return _custAccount  &&
          (select firstonly RecId from METCustTable
               where METCustTable.AccountNum == _custAccount).RecId != 0;
}

    /// <summary>
    /// Display method to get Industry channel
    /// </summary>
    /// <returns>Type METIndustryChannel</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METIndustryChannel displayMETIndustryChannel()
    {
        METIndustryKeyTable metIndustryKeyTable;

        select firstonly IndustryChannel 
            from metIndustryKeyTable
            where metIndustryKeyTable.IndustryKey == this.IndustryKey;

        return metIndustryKeyTable.IndustryChannel;
    }

    /// <summary>
    /// MPJ_8105 - kscerri - 02-07-2021
    /// </summary>
    /// <param name = "_fieldIdToCheck">Field id</param>
    /// <returns>if validation was successful</returns>
    public boolean validateField(FieldId _fieldIdToCheck)
    {
        boolean ret;
    
        ret = super(_fieldIdToCheck);
        
        if (ret)
        {
            switch (_fieldIdToCheck)
            {
                case fieldNum(METCustTable, CSAccountNum) :
                    if(this.CSLegalEntity)
                    {
                        if (!this.findCustByLE(this.CSLegalEntity, this.CSAccountNum))
                        {
                            ret = checkFailed(strFmt("@MET:CustAccNumValidation", this.CSAccountNum, this.CSLegalEntity));
                        }
                    }
                    break;

                case fieldNum(METCustTable, LinkedCustAccountNum) :
                    if(this.LinkedLegalEntity && this.LinkedCustAccountNum)
                    {
                        if (!this.findCustByLE(this.LinkedLegalEntity, this.LinkedCustAccountNum))
                        {
                            ret = checkFailed(strFmt("@MET:CustAccNumValidation", 
                                                     this.LinkedCustAccountNum, 
                                                     this.LinkedLegalEntity));
                        }
                    }
                    break;

                case fieldNum(METCustTable, AMEXChargeAccount) :
                    ret = CustTable::find(this.AMEXChargeAccount).checkBlockedAll();
                    break;
            }
        }

        return ret;
    }

    /// <summary>
    /// MPJ_8105 - kscerri - 02-07-2021
    /// Finds cross company customer account
    /// </summary>
    /// <param name = "_dataArea">data area id</param>
    /// <param name = "_custAccount">customer account</param>
    /// <returns>account num found</returns>
    public AccountNum findCustByLE(SelectableDataArea _dataArea, CustAccount _custAccount)
    {
        CustTable custTable;

        select firstonly crosscompany AccountNum from custTable
            where custTable.DataAreaId == _dataArea && custTable.AccountNum == _custAccount;

        return custTable.AccountNum;
    }

    /// <summary>
    /// /MPJ_15231_Customer Statement DCP 14/02/2022
    /// Finds cross company VAT number
    /// </summary>
    /// <returns>VAT num </returns>
    public VatNum getVatNumByLinkedAccount()
    {
        CustTable custTable;

        select firstonly crosscompany VATNum 
            from custTable
            where   custTable.DataAreaId == this.LinkedLegalEntity 
            &&      custTable.AccountNum == this.LinkedCustAccountNum;

        return custTable.VATNum;
    }

/// <summary>
/// MPJ_3338_METAMEXCustomerPaymentProcessing.
/// Finds the <C>METCustTable</C> buffer for the AMEX charge account.
/// </summary>
/// <returns><c>METCustTable</c></returns>
 METCustTable getAMEXChargeAccount()
{
    return METCustTable::find(this.AMEXChargeAccount);
}

/// <summary>
/// Insert the record
/// </summary>
public void insert()
{
    Global::handleEncryptedTablePreInsert(this);
    super();
    Global::handleEncryptedTablePostInsert(this);
}

    /// <summary>
    /// Update the record
    /// </summary>
    public void update()
    {
        boolean         fieldUpdated = false;
        METCustTable    metCustTableOrig = this.orig();

        if(this.CustOperGroupId != metCustTableOrig.CustOperGroupId
        || this.CBStore         != metCustTableOrig.CBStore
        || this.CBCTStopDate    != metCustTableOrig.CBCTStopDate)
        {
            fieldUpdated = true;
        }

        Global::handleEncryptedTablePreUpdate(this);
        super();
        Global::handleEncryptedTablePostUpdate(this);

        if(fieldUpdated)
        {
            METPriceChangeEventCustomer::metProcessTrackChange(this.custTable());
        }
    }

/// <summary>
/// Edits or displays the AMEX card number.
/// </summary>
/// <param name = "_set">True if value is updated; otherwise, false.</param>
/// <param name = "_value">AMEX card number.</param>
/// <returns>AMEX card number.</returns>
public edit Password amexCardNumEdit(boolean _set, Password _value)
{
    return Global::editEncryptedField(this, _value, fieldNum(METCustTable, AmexCardNum), _set);
}

/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing - vpotula
/// </summary>
/// <returns>Amex card number</returns>
public str getAmexCardNumber()
{
    return this.AmexCardNumberTxt;
}

    /// <summary>
    /// MPJ_3338_AMEXCustomerPaymentProcessing - vpotula
    /// Finds the specified record in the <c>METCustTable</c> table.
    /// </summary>
    /// <param name="_company">
    ///    The company for the customer record.
    /// </param>
    /// <param name="_custAccount">
    ///    The account number for the customer record.
    /// </param>
    /// <param name="_forUpdate">
    ///    A Boolean value that indicates whether to read the record for update; optional.
    /// </param>
    /// <returns>
    ///    A record in the <c>METCustTable</c> table; otherwise, an empty record.
    /// </returns>
    public static METCustTable findByCompany(
        DataAreaId _company,
        CustAccount _custAccount,
        boolean _forUpdate = false)
    {
        METCustTable cust;

        if (_company)
        {
            changecompany(_company)
            {
                cust = METCustTable::find(_custAccount, _forUpdate);
            }
        }

        return cust;
    }

    /// <summary>
    /// MPJ_3338_AMEXCustomerPaymentProcessing - vpotula
    /// Finds the specified record in the <c>METCustTable</c> table.
    /// </summary>
    /// <param name = "_ledgerDimension">ledgerdimension record id.</param>
    /// <param name = "_forupdate">
    ///    A Boolean value that indicates whether to read the record for update; optional.
    /// </param>
    /// <param name = "_concurrencyModel">ConcurrencyModel</param>
    /// <returns>
    ///  A record in the <c>METCustTable</c> table; otherwise, an empty record.
    /// </returns>
    public static METCustTable findByLedgerDimension(
        LedgerDimensionAccount  _ledgerDimension,
        boolean                 _forupdate = false,
        ConcurrencyModel        _concurrencyModel = ConcurrencyModel::Auto)
    {
        METCustTable                        custTable;
        DimensionAttributeValueCombination  ledgerDimension;

        custTable.selectForUpdate(_forupdate);
        if (_forupdate  && _concurrencyModel != ConcurrencyModel::Auto)
        {
            custTable.concurrencyModel(_concurrencyModel);
        }

        select firstonly custTable
            exists join ledgerDimension where
                ledgerDimension.DisplayValue == custTable.AccountNum &&
                ledgerDimension.RecId == _ledgerDimension;

        return custTable;
    }

/// <summary>
/// get the customer table
/// </summary>
public CustTable custTable()
{
    return CustTable::find(this.AccountNum);
}

    /// <summary>
    /// get the Price Data Extract number seq for the customer
    /// </summary>
    /// <param name = "_custAccount">Customer account</param>
    /// <returns>Price Data Extract number seq</returns>
    public static METCustPriceDataExtractId getPriceDataExtractId(custAccount _custAccount)
    {
        METCustTable  metCustTable;

        if(_custAccount)
        {
            select firstOnly PriceDataExtractId
                from    metCustTable
                where   metCustTable.AccountNum == _custAccount;
        }

        return metCustTable.PriceDataExtractId;
    }

    /// <summary>
    /// Get the Data Extract Id number sequence
    /// </summary>
    /// <param name = "_NumberSequenceCode">Number sequence</param>
    /// <returns>Data Extract Id number sequence</returns>
    public static METCustPriceDataExtractId setPriceExtractIdFromNumSeq(NumberSequenceCode _NumberSequenceCode)
    {
        NumberSequenceTable NumberSequenceTable;

        select  firstonly RecId from NumberSequenceTable
            where NumberSequenceTable.NumberSequence == _NumberSequenceCode;

        return NumberSequenceTable.RecId;
    }
